import{_ as o,y as s,a,o as n,a2 as r,D as i}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Omnibus Price Disclosure","description":"","frontmatter":{},"headers":[],"relativePath":"configure/omnibus.md","filePath":"configure/omnibus.md","lastUpdated":1789411722000}'),c={name:"configure/omnibus.md"};function h(u,e,l,p,d,m){const t=s("ImagePopup");return n(),a("div",null,[e[0]||(e[0]=r('<h1 id="omnibus-price-disclosure" tabindex="-1">Omnibus Price Disclosure <a class="header-anchor" href="#omnibus-price-disclosure" aria-label="Permalink to &quot;Omnibus Price Disclosure&quot;">​</a></h1><p>The EU Omnibus Directive requires a store that announces a discount to show the lowest price it charged for that product in the 30 days before the discount. Bagisto can record product prices as they change and show that lowest price next to a discounted price on the storefront. This section is available in Bagisto 2.5.</p><h2 id="turn-on-price-disclosure" tabindex="-1">Turn on price disclosure <a class="header-anchor" href="#turn-on-price-disclosure" aria-label="Permalink to &quot;Turn on price disclosure&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Omnibus Price Disclosure</strong>, switch <strong>Enable Omnibus Disclosure</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),i(t,{src:"/images/configure/products-omnibus.png",alt:"Omnibus Price Disclosure section of the Products screen"}),e[1]||(e[1]=r('<p>The setting is per channel, so turn it on for each channel that sells to consumers in the EU.</p><h2 id="what-the-customer-sees" tabindex="-1">What the customer sees <a class="header-anchor" href="#what-the-customer-sees" aria-label="Permalink to &quot;What the customer sees&quot;">​</a></h2><p>When a product is sold below its regular price, through a special price, a catalog rule or a customer group price, the product page and listings show a line under the price:</p><p><strong>Lowest price 30 days prior to the discount:</strong> followed by that price.</p><p>The line only appears when there is a discount and when there are recorded prices to compare against.</p><h2 id="where-the-prices-come-from" tabindex="-1">Where the prices come from <a class="header-anchor" href="#where-the-prices-come-from" aria-label="Permalink to &quot;Where the prices come from&quot;">​</a></h2><p>Once the setting is on, the store records every product&#39;s price whenever it changes, checking every fifteen minutes, and keeps 35 days of history, so the 30-day comparison is always complete. Both the recording and the daily clean-up run on the server&#39;s scheduler, so if the line never appears on a store that has been enabled for more than a day, ask whoever manages the server to check that the scheduler is running.</p><p>A newly enabled store has no history yet. The first prices are recorded on the next scheduled run, and the lowest price shown grows more meaningful as the days accumulate.</p>',8))])}const _=o(c,[["render",h]]);export{f as __pageData,_ as default};
